record.field:
for picking in env['stock.picking'].search([
    ('activity_ids.activity_type_id', '=', env.ref(
        'fmcg_business_automation.mail_activity_type_picking_assigned'
    ).id),
    ('activity_ids', 'not any', [
        ('activity_type_id', '=', env.ref(
            'fmcg_business_automation.mail_activity_type_picking_existing_lot_serial'
        ).id),
    ]),
    ('state', 'not in', ['draft', 'done', 'cancel']),
    ('picking_type_id.code', '!=', 'incoming'),
    ('move_line_ids', 'any', [
        ('product_id.tracking', 'in', ['lot', 'serial']),
        ('quantity', '>', 0),
        ('lot_id', '=', False),
    ]),
], limit=100):
    picking.activity_schedule(
        'fmcg_business_automation.mail_activity_type_picking_existing_lot_serial'
    )

for activity in records:
    picking = env['stock.picking'].browse(activity.res_id).exists()

    if not picking:
        continue

    # This action only simulates filling a lot on the move line.  It must not
    # enforce the picking type UI configuration or duplicate core validation.
    if picking.picking_type_id.code == 'incoming':
        continue

    missing_lines = picking.move_line_ids.filtered(
        lambda line: line.quantity > 0
        and line.product_id.tracking in ('lot', 'serial')
        and not line.lot_id
    )
    allocated_by_lot = {}

    for line in missing_lines:
        if line.product_id.tracking == 'serial' and line.quantity != 1:
            # Leave the line untouched. Core validation owns the error for an
            # invalid serial quantity.
            continue

        quants = env['stock.quant'].search([
            ('product_id', '=', line.product_id.id),
            ('location_id', 'child_of', line.location_id.id),
            ('lot_id', '!=', False),
            ('company_id', '=', picking.company_id.id),
        ], order='in_date, id')

        available_by_lot = {}
        lot_by_id = {}
        for quant in quants:
            available = quant.quantity - quant.reserved_quantity
            if available > 0:
                lot_by_id[quant.lot_id.id] = quant.lot_id
                available_by_lot[quant.lot_id.id] = (
                    available_by_lot.get(quant.lot_id.id, 0) + available
                )

        selected_lot = False
        for lot_id, available in available_by_lot.items():
            allocated = allocated_by_lot.get(
                (line.product_id.id, line.location_id.id, lot_id),
                0,
            )
            if available - allocated >= line.quantity:
                selected_lot = lot_by_id[lot_id]
                break

        if not selected_lot:
            # Leave the line without a lot. Core validation will report the
            # missing Lot/Serial when the picking is validated.
            continue

        line.write({'lot_id': selected_lot.id})
        allocation_key = (
            line.product_id.id,
            line.location_id.id,
            selected_lot.id,
        )
        allocated_by_lot[allocation_key] = (
            allocated_by_lot.get(allocation_key, 0) + line.quantity
        )
